(function(root){
'use strict';
function normalize(value){return value.normalize('NFKC').toLocaleLowerCase().trim();}
function distance(a,b){a=Array.from(normalize(a));b=Array.from(normalize(b));if(a.length>200||b.length>200)throw Error('Fuzzy terms must be at most 200 characters');let previous=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){const next=[i+1];for(let j=0;j<b.length;j++)next.push(Math.min(next[j]+1,previous[j+1]+1,previous[j]+(a[i]===b[j]?0:1)));previous=next;}return previous[b.length];}
function find(records,query,mode='all'){if(!['all','exact','fuzzy'].includes(mode))throw Error('Unknown search mode');const q=normalize(query);if(q.length>200)throw Error('Query must be at most 200 characters');const terms=q.split(/\s+/).filter(Boolean);const found=[];for(const record of records){const name=normalize(record.name),text=normalize(record.name+' '+record.purpose+' '+record.review);let score=0,reason='';if(!q){score=1;reason='Browse';}else if(mode==='exact'&&name===q){score=100;reason='Exact name';}else if(mode==='all'&&terms.every(term=>text.includes(term))){score=name===q?100:name.includes(q)?90:60;reason='All search terms found';}else if(mode==='fuzzy'){const candidates=[name,...name.split(/\s+/)];const best=Math.min(...candidates.filter(s=>Array.from(s).length<=200).map(s=>distance(q,s)));const threshold=Math.max(1,Math.min(3,Math.floor(Array.from(q).length/4)));if(best<=threshold){score=80-best*10;reason='Approximate name, edit distance '+best;}}if(score)found.push({...record,score,reason});}return found.sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name));}
function fractions(value){if(!/^-?\d+$/.test(value)||value.length>1000)throw Error('Use integers of at most 1000 characters');return BigInt(value);}
function calculate(a,b,op){const x=fractions(a),y=fractions(b);switch(op){case 'add':return String(x+y);case 'subtract':return String(x-y);case 'multiply':return String(x*y);case 'divide':if(!y)throw Error('Division by zero');return String(x/y)+' remainder '+String(x%y);case 'gcd':{let u=x<0n?-x:x,v=y<0n?-y:y;while(v){[u,v]=[v,u%v];}return String(u);}default:throw Error('Unknown operation');}}
root.RasnikiSearch={normalize,distance,find,calculate};
})(globalThis);
